/**
 * Comprehensive tests for native Anthropic tool extraction and response reconstruction.
 *
 * Tests the full pipeline:
 *   1. extractToolsFromResponseFormat() — extract tools from response_format JSON schema
 *   2. reconstructAgentResponse() — rebuild JSON the agent expects from Anthropic response
 *   3. Streaming transform — validate JSON escaping and tool_calls serialization
 *
 * All fixtures mirror real production schemas generated by the Python agent's
 * prepare_schema_for_openai(create_agent_action_model(EXECUTE_PHASE_TOOLS)).
 *
 * Run: node test-native-tool-extraction.mjs
 */

// ============================================================================
// Mirror functions from index.ts (so we can test without Deno imports)
// ============================================================================

function transformSchemaForAnthropic(schema) {
  if (!schema || typeof schema !== 'object') return schema;

  const transformed = { ...schema };

  const unsupported = ['minimum', 'maximum', 'minLength', 'maxLength', 'multipleOf', 'minItems', 'maxItems'];
  for (const key of unsupported) {
    delete transformed[key];
  }

  if (transformed.type === 'object' && typeof transformed.additionalProperties === 'object' && transformed.additionalProperties !== null) {
    transformed.additionalProperties = false;
  }

  if (transformed.properties) {
    transformed.properties = { ...transformed.properties };
    for (const key of Object.keys(transformed.properties)) {
      transformed.properties[key] = transformSchemaForAnthropic(transformed.properties[key]);
    }
  }

  if (transformed.items) {
    transformed.items = transformSchemaForAnthropic(transformed.items);
  }

  if (transformed.$defs) {
    transformed.$defs = { ...transformed.$defs };
    for (const key of Object.keys(transformed.$defs)) {
      transformed.$defs[key] = transformSchemaForAnthropic(transformed.$defs[key]);
    }
  }

  for (const keyword of ['anyOf', 'oneOf', 'allOf']) {
    if (transformed[keyword] && Array.isArray(transformed[keyword])) {
      transformed[keyword] = transformed[keyword].map((item) => transformSchemaForAnthropic(item));
    }
  }

  return transformed;
}

function extractToolsFromResponseFormat(responseFormat) {
  const schema = responseFormat?.json_schema?.schema;
  if (!schema?.properties?.tool_calls?.items?.anyOf) return null;

  const anyOfVariants = schema.properties.tool_calls.items.anyOf;
  if (!anyOfVariants.every((v) => v.properties?.tool?.const)) return null;

  const tools = [];

  for (const variant of anyOfVariants) {
    const toolName = variant.properties.tool.const;
    const description = variant.description || '';

    const inputProperties = { ...variant.properties };
    delete inputProperties.tool;

    const required = (variant.required || []).filter((r) => r !== 'tool');

    const inputSchema = {
      type: 'object',
      properties: inputProperties,
      required,
    };

    if (variant.additionalProperties !== undefined) {
      inputSchema.additionalProperties = variant.additionalProperties;
    }

    tools.push({
      name: toolName,
      description,
      input_schema: transformSchemaForAnthropic(inputSchema),
    });
  }

  const responseFieldSchema = schema.properties.response || { type: 'string' };

  return { tools, responseFieldSchema };
}

function reconstructAgentResponse(textContent, toolUseBlocks) {
  const toolCalls = toolUseBlocks.map(t => ({
    tool: t.name,
    ...t.input,
  }));
  return JSON.stringify({ response: textContent, tool_calls: toolCalls });
}

function applyAnthropicToolConfig(anthropicBody, responseFormat, isClaudeAuth, explicitTools, explicitToolChoice) {
  const extractedTools = extractToolsFromResponseFormat(responseFormat);

  if (extractedTools) {
    anthropicBody.tools = extractedTools.tools;
    anthropicBody.tool_choice = { type: 'auto' };
    return true;
  }

  if (explicitTools?.length) {
    anthropicBody.tools = explicitTools.map((t) => ({
      name: t.function?.name ?? t.name,
      description: t.function?.description ?? t.description,
      input_schema: t.function?.parameters ?? t.input_schema,
    }));
    if (explicitToolChoice) {
      if (explicitToolChoice === 'auto') anthropicBody.tool_choice = { type: 'auto' };
      else if (explicitToolChoice === 'required' || explicitToolChoice === 'any') anthropicBody.tool_choice = { type: 'any' };
      else if (explicitToolChoice?.function?.name) anthropicBody.tool_choice = { type: 'tool', name: explicitToolChoice.function.name };
    }
    return false;
  }

  if (responseFormat?.json_schema?.schema) {
    const transformedSchema = transformSchemaForAnthropic(responseFormat.json_schema.schema);
    if (isClaudeAuth) {
      anthropicBody.output_config = {
        format: { type: 'json_schema', schema: transformedSchema }
      };
    } else {
      anthropicBody.output_format = {
        type: 'json_schema',
        schema: transformedSchema
      };
    }
  }

  return false;
}

