function testStreamingJsonEscaping() {
  console.log('\n=== Test: Streaming JSON escaping simulation ===');

  // Simulate the streaming escape logic from handleStreaming
  const textDeltas = [
    'Hello, I will help you with that.\n',
    'Let me search for "recent emails" from your account.\n',
    'Here\'s what I found:\t',
    'Result with backslash \\ and unicode.'
  ];

  // Mimic the streaming escape logic
  let accumulated = '';
  const escaped_chunks = [];
  for (const delta of textDeltas) {
    const escaped = delta
      .replace(/\\/g, '\\\\')
      .replace(/"/g, '\\"')
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '\\r')
      .replace(/\t/g, '\\t');
    escaped_chunks.push(escaped);
    accumulated += delta;
  }

  // Build the full streamed JSON
  const streamedJson = '{"response": "' + escaped_chunks.join('') + '", "tool_calls": []}';

  // Verify the assembled JSON is parseable
  let parsed;
  try {
    parsed = JSON.parse(streamedJson);
    assert(true, 'Streamed JSON should be valid');
  } catch (e) {
    assert(false, `Streamed JSON is invalid: ${e.message}\nJSON: ${streamedJson.slice(0, 200)}`);
    return;
  }

  assert(parsed.response === accumulated, 'Parsed response should match accumulated text');
  assert(parsed.response.includes('"recent emails"'), 'Should contain original double quotes');
  assert(parsed.response.includes('\n'), 'Should contain original newlines');
  assert(parsed.response.includes('\t'), 'Should contain original tabs');
  assert(parsed.response.includes('\\'), 'Should contain original backslash');
}

function testStreamingWithToolCalls() {
  console.log('\n=== Test: Streaming JSON with tool_calls at end ===');

  // Simulate the complete streamed output: prefix + text + closing with tools
  const responseText = 'Searching for your emails now.';
  const toolCalls = [
    { tool: 'spawn_browser_agent', start_url: 'https://mail.google.com', goal: 'Read recent emails', output_schema: { fields: [] }, attachments: null }
  ];

  const escaped = responseText
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');

  const chunks = [];
  chunks.push('{"response": "');
  chunks.push(escaped);
  chunks.push(`", "tool_calls": ${JSON.stringify(toolCalls)}}`);

  const fullJson = chunks.join('');
  let parsed;
  try {
    parsed = JSON.parse(fullJson);
    assert(true, 'Streaming with tools should produce valid JSON');
  } catch (e) {
    assert(false, `Invalid JSON: ${e.message}`);
    return;
  }

  assert(parsed.response === responseText, 'Response text matches');
  assert(parsed.tool_calls.length === 1, 'Should have 1 tool call');
  assert(parsed.tool_calls[0].tool === 'spawn_browser_agent', 'Tool name matches');
  assert(parsed.tool_calls[0].start_url === 'https://mail.google.com', 'start_url matches');
}

